namespace ghidra.feature.vt.gui.actions;



using docking;
using docking.action;
using docking.tool;
using docking.wizard;
using generic.theme;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.wizard.add;
using ghidra.util;

public class AddToVersionTrackingSessionAction : DockingAction {

	private VTController controller;

	public AddToVersionTrackingSessionAction(VTController controller) : base("Add To Session", VTPlugin.OWNER)
    {
		this.controller = controller;
		string[] menuPath = new string[] { ToolConstants.MENU_FILE, "Add to Session..." };
		Icon plusIcon = new GIcon("icon.version.tracking.action.add.to.session");
		setMenuBarData(new MenuData(menuPath, plusIcon, "AAA"));
		setToolBarData(new ToolBarData(plusIcon, "View"));
		setDescription("Add additional correlations to the current version tracking session");
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Add_To_Session"));

	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		VTAddToSessionWizardModel model = new VTAddToSessionWizardModel(controller);
		WizardDialog wizardDialog = new WizardDialog(model);
		wizardDialog.show(controller.getParentComponent());
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return controller.getSession() != null;
	}
}
